You assess retrieved reference tests for unit-test generation.
A generator must write a Hardhat (ethers 6, Mocha/Chai) unit-test suite for the TARGET Solidity contract below.
It receives example tests retrieved from a corpus of OTHER contracts. Such examples are never written for the target:
a different contract name is expected and is NOT a reason for a low rating. Judge only their value as a template.

Rate the RETRIEVED TEST:
2 = directly adaptable: it exercises a behaviour that the target also implements (same kind of operation, state change,
    access rule or revert condition); its setup, calls, assertions or revert checks could be reused after renaming.
1 = partially useful: it shows a generic testing pattern applicable to the target (e.g., access-control revert, event
    assertion, time manipulation, balance change, deployment with constructor arguments), but the specific behaviour it
    tests does not exist in the target.
0 = not useful: neither its behaviour nor its testing pattern applies to the target.

Give a reason of at most 30 words, then the rating.

TARGET CONTRACT:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract SimpleStorage {
    uint256 private storedData;

    function set(uint256 value) external {
        storedData = value;
    }

    function get() external view returns (uint256) {
        return storedData;
    }
}

RETRIEVED TEST:
// corpus-v2 pair land-registry--vaishnavadevi-r (registries-identity, complex)
// LandRegistry.test.js: LandRegistry > should allow an authority to register a property
const { expect } = require("chai");
const hre = require("hardhat");
let landRegistry;
let admin;
let authority;
let verifier;
let owner;
let buyer;
let unauthorized;
const PROPERTY_ID = 1001;
const PROPERTY_NUMBER = "P001";
const LOCATION = "Coimbatore, Tamil Nadu";
const AREA = 1200;
const PROPERTY_TYPE = "Residential";
const DOCUMENT_HASH =
        hre.ethers.keccak256(
            hre.ethers.toUtf8Bytes("property-001-document")
        );
// beforeEach of suite "LandRegistry"
beforeEach(async function () {

        [
            admin,
            authority,
            verifier,
            owner,
            buyer,
            unauthorized
        ] = await hre.ethers.getSigners();

        const LandRegistry =
            await hre.ethers.getContractFactory("LandRegistry");

        landRegistry = await LandRegistry.deploy();

        await landRegistry.waitForDeployment();

        // Give roles to test accounts
        await landRegistry
            .connect(admin)
            .addAuthority(authority.address);

        await landRegistry
            .connect(admin)
            .addVerifier(verifier.address);
    })
it("should allow an authority to register a property", async function () {

        await expect(
            landRegistry
                .connect(authority)
                .registerProperty(
                    PROPERTY_ID,
                    PROPERTY_NUMBER,
                    LOCATION,
                    AREA,
                    PROPERTY_TYPE,
                    owner.address,
                    DOCUMENT_HASH
                )
        )
            .to.emit(landRegistry, "PropertyRegistered")
            .withArgs(
                PROPERTY_ID,
                PROPERTY_NUMBER,
                owner.address,
                (value) => value > 0
            );

        const property =
            await landRegistry.getProperty(PROPERTY_ID);

        expect(property.propertyId)
            .to.equal(PROPERTY_ID);

        expect(property.propertyNumber)
            .to.equal(PROPERTY_NUMBER);

        expect(property.location)
            .to.equal(LOCATION);

        expect(property.area)
            .to.equal(AREA);

        expect(property.propertyType)
            .to.equal(PROPERTY_TYPE);

        expect(property.currentOwner)
            .to.equal(owner.address);

        expect(property.verified)
            .to.equal(false);
    })


